+static int exif_clone_entry(AVExifEntry *dst, const AVExifEntry *src)
+{
+    int ret = 0;
+
+    dst->count = src->count;
+    dst->id = src->id;
+    dst->type = src->type;
+
+    dst->ifd_offset = src->ifd_offset;
+    if (src->ifd_lead) {
+        dst->ifd_lead = av_memdup(src->ifd_lead, src->ifd_offset);
